CAT = "itceliTesti"; SEG = "TES"
# Comprensione della lettura: email, lettere, articoli e racconti brevi (stile A.2), due domande
# per testo. Le due domande di un testo sono vicine, quindi finiscono nella stessa prova.
T = [
("Email: «Cara Fiorella, finalmente ho trovato casa a Trento! È un trilocale piccolo ma luminoso, in una via tranquilla vicino al fiume. L'affitto è un po' più alto di quello che pensavo, però non devo più prendere l'autobus per andare al lavoro: ci vado in bicicletta in dieci minuti. L'unico problema è la cucina, che è vecchia, ma il proprietario ha promesso di cambiarla entro la primavera. Quando vieni a trovarmi? Il divano è comodo anche per dormire! Un abbraccio, Noemi»",
 [("Perché Noemi è contenta della nuova casa, anche se costa di più?",
   "Può andare al lavoro in bici", ["La cucina è appena stata rifatta", "È vicina alla fermata dell'autobus", "Ha una camera in più per gli ospiti"],
   "Noemi dice che l'affitto è più alto, «però» non deve più prendere l'autobus: va al lavoro in bicicletta in dieci minuti."),
  ("Che cosa farà il proprietario?",
   "Cambierà la cucina", ["Abbasserà l'affitto", "Comprerà un divano letto", "Ridipingerà le pareti"],
   "Il proprietario ha promesso di cambiare la cucina vecchia entro la primavera. Dell'affitto non si parla come di qualcosa che cambierà.")]),
("Articolo: «A Castelfranco Veneto da settembre la biblioteca comunale presta non solo libri, ma anche attrezzi: trapani, scale, macchine per cucire e persino una tenda da campeggio. L'idea è nata da un gruppo di pensionati che si sono accorti di avere in cantina oggetti usati una volta all'anno. Per prendere un attrezzo basta la tessera della biblioteca; il prestito dura una settimana. Nei primi due mesi gli oggetti più richiesti sono stati il trapano e la macchina per la pasta.»",
 [("Da dove è venuta l'idea del prestito di attrezzi?",
   "Da alcuni pensionati del posto", ["Dal sindaco della città", "Da un negozio di ferramenta", "Dai bibliotecari stessi"],
   "L'articolo dice che l'idea è nata da un gruppo di pensionati con oggetti inutilizzati in cantina."),
  ("Che cosa serve per prendere in prestito un attrezzo?",
   "La tessera della biblioteca", ["Una cauzione in contanti", "Un documento e la bolletta", "La prenotazione un mese prima"],
   "Per il prestito «basta la tessera della biblioteca». Il prestito dura una settimana.")]),
("Lettera a una rivista: «Gentile redazione, abito a Varese e ogni mattina porto mio figlio a scuola a piedi. Da qualche mese davanti al cancello si fermano decine di auto in doppia fila, e attraversare è diventato pericoloso. Ne ho parlato con altri genitori e abbiamo proposto al Comune di chiudere la strada al traffico dieci minuti prima e dopo l'inizio delle lezioni. Finora non abbiamo ricevuto risposta. Voi che cosa ne pensate? Ermanno C.»",
 [("Qual è il problema che descrive Ermanno?",
   "Le auto in doppia fila", ["La scuola è troppo lontana da casa", "Il figlio arriva sempre in ritardo", "Mancano insegnanti nella scuola"],
   "Ermanno racconta che le auto in doppia fila davanti al cancello rendono pericoloso attraversare."),
  ("Che cosa hanno chiesto i genitori al Comune?",
   "Di vietare il traffico per poco tempo", ["Di costruire un parcheggio", "Di spostare la scuola", "Di cambiare l'orario delle lezioni"],
   "I genitori hanno proposto di chiudere la strada dieci minuti prima e dopo l'inizio delle lezioni, non di cambiare l'orario.")]),
("Racconto: «Quando Saverio arrivò alla stazione di Lucca, pioveva forte e l'ultimo autobus per il paese era già partito. Il telefono era scarico, perché aveva passato il viaggio a guardare film. Entrò nel bar della stazione per chiedere un taxi, e la barista gli disse che a quell'ora ne girava uno solo. Mentre aspettava, un signore anziano seduto al bancone gli chiese dove doveva andare: abitava proprio nel paese vicino e gli offrì un passaggio.»",
 [("Perché Saverio non poteva chiamare nessuno?",
   "Il cellulare non aveva più batteria", ["Al bar non c'era campo", "Non aveva il numero del taxi", "Il bar era già chiuso"],
   "Il telefono era scarico perché Saverio aveva guardato film durante il viaggio."),
  ("Come risolve il problema Saverio?",
   "Accetta un passaggio da un signore", ["Prende l'ultimo autobus", "Dorme in un albergo vicino", "Aspetta il taxi per un'ora"],
   "Un signore anziano che abitava nel paese vicino gli offre un passaggio. L'ultimo autobus era già partito.")]),
("Email di lavoro: «Gentile dottoressa Benvenuti, le scrivo a nome della ditta Ferrari Arredi. Purtroppo il tavolo che ha ordinato non arriverà il 12, come previsto, perché il nostro fornitore ha avuto un ritardo con il legno. Possiamo consegnarlo il 26 senza costi di trasporto, oppure restituirle subito l'acconto, se preferisce annullare l'ordine. Ci scusiamo per il disagio e restiamo a disposizione. Cordiali saluti, Cesare Monti»",
 [("Perché il tavolo arriverà in ritardo?",
   "Il legno è arrivato tardi", ["Il trasporto costava troppo", "La cliente ha cambiato modello", "Il tavolo è arrivato rotto"],
   "Il ritardo dipende dal fornitore, che ha avuto problemi con il legno."),
  ("Che cosa offre la ditta alla cliente?",
   "La consegna gratis o i soldi indietro", ["Uno sconto su un altro tavolo", "Un tavolo diverso il giorno 12", "Il montaggio senza pagare"],
   "La ditta propone la consegna il 26 senza costi di trasporto oppure la restituzione dell'acconto.")]),
("Articolo: «Nel piccolo comune di Cerreto, in Molise, la scuola elementare rischiava di chiudere perché c'erano solo nove bambini. Il sindaco ha deciso di offrire una casa in affitto a prezzo bassissimo alle famiglie con figli che si trasferiscono in paese. In due anni sono arrivate sei famiglie, alcune da Roma e una dalla Germania. Oggi la scuola ha diciotto alunni e ha assunto una nuova maestra di musica.»",
 [("Qual era il problema del paese?",
   "C'erano pochi alunni", ["Le case erano troppo care", "Mancava un medico", "La scuola era molto vecchia"],
   "La scuola rischiava di chiudere perché c'erano solo nove bambini."),
  ("Che cosa è successo dopo la decisione del sindaco?",
   "Gli alunni sono raddoppiati", ["La scuola ha chiuso lo stesso", "Sono partite sei famiglie", "La maestra di musica è andata via"],
   "Da nove alunni la scuola è passata a diciotto, cioè il doppio, e ha assunto una maestra di musica.")]),
("Email: «Ciao Tiziano, ti scrivo per la cena di classe di sabato. Il ristorante sul porto di Chioggia ci fa un menù di pesce a 35 euro, bevande comprese, ma vuole sapere il numero preciso entro mercoledì. Finora siamo in ventidue. Se qualcuno è vegetariano, il cuoco prepara un primo e un secondo diversi, basta dirlo prima. Puoi chiedere tu a quelli del gruppo che non hanno ancora risposto? Grazie, Ludovica»",
 [("Che cosa chiede Ludovica a Tiziano?",
   "Di sentire chi non ha risposto", ["Di prenotare il ristorante", "Di pagare la cena per tutti", "Di scegliere il menù di pesce"],
   "Ludovica chiede a Tiziano di contattare le persone del gruppo che non hanno ancora risposto."),
  ("Che cosa succede per chi non mangia pesce né carne?",
   "Avrà piatti a parte", ["Paga meno degli altri", "Deve portarsi il cibo", "Mangia solo il dolce"],
   "Il cuoco prepara un primo e un secondo diversi per i vegetariani, a patto che lo si dica prima.")]),
("Testo informativo: «Il Parco nazionale della Sila, in Calabria, è famoso per i suoi boschi di pini larici, alberi alti anche quaranta metri. In inverno sui monti cade spesso la neve e si può sciare, mentre d'estate molti turisti arrivano per camminare e andare in canoa sul lago Arvo. Nel parco vivono lupi e cervi, che però è raro vedere, perché si avvicinano poco ai sentieri. Il centro visite di Cupone organizza escursioni guidate tutto l'anno.»",
 [("Che cosa si può fare d'estate nel parco?",
   "Fare una gita in canoa", ["Sciare sulle piste", "Dare da mangiare ai lupi", "Pescare nel mare vicino"],
   "D'estate i turisti camminano e vanno in canoa sul lago Arvo. Lo sci è un'attività dell'inverno."),
  ("Perché è difficile vedere i lupi?",
   "Stanno lontano dai sentieri", ["Vivono solo in inverno", "Sono tutti chiusi in un recinto", "Sono scomparsi dal parco"],
   "Lupi e cervi vivono nel parco, ma si avvicinano poco ai sentieri, quindi è raro vederli.")]),
("Lettera: «Cara nonna, qui a Edimburgo va tutto bene. Il corso all'università è difficile, soprattutto le lezioni di statistica, ma ho trovato due compagni italiani con cui studio la sera. Ho anche cominciato a lavorare in un caffè il sabato: guadagno poco, però così parlo inglese tutto il giorno. L'unica cosa che mi manca davvero è la tua cucina! A Natale torno per due settimane. Ti voglio bene, Carlotta»",
 [("Perché Carlotta lavora nel caffè?",
   "Per esercitarsi con l'inglese", ["Per pagare tutto l'affitto", "Perché il corso è finito", "Per conoscere altri italiani"],
   "Carlotta dice che guadagna poco, «però così» parla inglese tutto il giorno: lo scopo principale è la lingua."),
  ("Che cosa trova difficile Carlotta?",
   "Una delle materie del corso", ["Trovare amici italiani", "Il lavoro del sabato", "Il viaggio per tornare a casa"],
   "Carlotta dice che il corso è difficile, soprattutto le lezioni di statistica.")]),
("Articolo: «Sempre più ristoranti di Torino offrono ai clienti una scatola per portare a casa il cibo avanzato. L'iniziativa, sostenuta dal Comune, vuole ridurre lo spreco. Secondo un'indagine, molti clienti non chiedevano la scatola per vergogna. Ora è il cameriere a proporla alla fine del pasto. I ristoratori dicono che la richiesta è aumentata del cinquanta per cento in un anno.»",
 [("Perché prima molti clienti non chiedevano la scatola?",
   "Si sentivano in imbarazzo", ["Costava troppo", "Il Comune lo vietava", "I ristoranti non l'avevano"],
   "L'indagine dice che molti non la chiedevano «per vergogna», cioè per imbarazzo."),
  ("Che cosa è cambiato nei ristoranti?",
   "La propone il cameriere", ["La scatola si paga a parte", "Le porzioni sono più piccole", "Si può prendere solo a pranzo"],
   "Adesso è il cameriere a proporre la scatola alla fine del pasto, e le richieste sono aumentate.")]),
("Email: «Gentile signor Rinaldi, la ringraziamo per la sua domanda di lavoro come magazziniere. Il suo profilo ci interessa e vorremmo incontrarla martedì 18 alle 15 nella nostra sede di Prato. Il colloquio durerà circa mezz'ora. Le chiediamo di portare una copia della patente del muletto e, se le ha, delle lettere di referenze. Se l'orario non le va bene, ci chiami per fissarne un altro. Ufficio personale, Logistica Bisenzio»",
 [("Perché l'azienda scrive al signor Rinaldi?",
   "Per invitarlo a un colloquio", ["Per offrirgli subito il posto", "Per dirgli che non è stato scelto", "Per chiedere il suo curriculum"],
   "L'azienda dice che il profilo interessa e propone un incontro martedì alle 15: è un invito a un colloquio."),
  ("Che cosa deve portare il signor Rinaldi?",
   "Un documento sul muletto", ["Il contratto firmato", "Il diploma della scuola", "Una foto per il badge"],
   "Gli chiedono una copia della patente del muletto e, se le ha, lettere di referenze.")]),
("Testo: «Ogni anno, l'ultima domenica di settembre, il paese di Montefalco organizza una festa per la fine della vendemmia. Le cantine aprono le porte ai visitatori, che possono assaggiare il vino e vedere come si lavora l'uva. Nel pomeriggio c'è una sfilata di carri decorati con grappoli e foglie, preparati per mesi dai quattro quartieri del paese. Il carro più bello vince un premio, ma per tutti c'è una cena in piazza.»",
 [("Che cosa si festeggia a Montefalco?",
   "La fine della raccolta dell'uva", ["L'apertura di una nuova cantina", "Il santo patrono del paese", "L'arrivo dell'autunno"],
   "La festa è per la fine della vendemmia, cioè della raccolta dell'uva."),
  ("Chi prepara i carri della sfilata?",
   "Gli abitanti dei vari quartieri", ["Le cantine della zona", "Una ditta di fuori", "I turisti in visita"],
   "I carri sono preparati per mesi dai quattro quartieri del paese.")]),
("Messaggio su un forum: «Ciao a tutti, a giugno vorrei fare il Cammino di San Francesco da La Verna ad Assisi, circa dieci giorni a piedi. Non ho mai fatto un viaggio così lungo e ho un dubbio: è meglio prenotare tutti gli ostelli prima di partire, o si trova posto anche all'ultimo momento? Ho letto che d'estate alcuni posti sono pieni. Grazie a chi risponde! Gianmarco»",
 [("Che cosa vuole sapere Gianmarco?",
   "Se deve prenotare in anticipo i letti", ["Quanto costa il cammino", "Quale strada è più corta", "Se può portare il cane"],
   "Il suo dubbio è se prenotare gli ostelli prima di partire o se si trova posto all'ultimo momento."),
  ("Che cosa ha già letto Gianmarco?",
   "Che d'estate c'è poco posto", ["Che il cammino è chiuso a giugno", "Che servono venti giorni", "Che gli ostelli sono gratuiti"],
   "Gianmarco ha letto che d'estate alcuni posti sono pieni, ed è per questo che fa la domanda.")]),
("Articolo: «A Parma una cooperativa ha aperto un orto in città su un terreno abbandonato vicino alla tangenziale. Gli orti sono divisi in quaranta piccoli lotti, assegnati per due anni agli abitanti del quartiere che ne fanno richiesta. Chi riceve un lotto deve coltivarlo senza prodotti chimici e partecipare una volta al mese alla pulizia degli spazi comuni. Ci sono già più domande che lotti disponibili.»",
 [("Per quanto tempo si può avere un lotto?",
   "Per due anni", ["Per un mese", "Per sempre", "Per una sola stagione"],
   "I lotti sono assegnati per due anni agli abitanti del quartiere."),
  ("Che cosa deve fare chi ha un lotto?",
   "Aiutare a pulire le parti comuni", ["Vendere la verdura alla cooperativa", "Usare solo i concimi del negozio", "Pagare un affitto ogni mese"],
   "Chi ha un lotto coltiva senza prodotti chimici e partecipa una volta al mese alla pulizia degli spazi comuni.")]),
("Email: «Ciao Annarita, grazie per l'invito al battesimo di Pietro! Purtroppo quel fine settimana sono a Bari per il matrimonio di mia cugina, organizzato da più di un anno. Mi dispiace tantissimo. Posso passare da voi la settimana dopo per conoscere il piccolo e portargli il mio regalo? Dimmi tu quale giorno vi va meglio. Baci, Debora»",
 [("Perché Debora non va al battesimo?",
   "Ha un altro impegno di famiglia", ["Non è stata invitata", "Non sta bene", "Deve lavorare a Bari"],
   "Debora quel fine settimana è a Bari per il matrimonio della cugina."),
  ("Che cosa propone Debora?",
   "Di passare la settimana successiva", ["Di spostare il battesimo", "Di mandare il regalo per posta", "Di vedersi a Bari"],
   "Debora chiede di passare la settimana dopo per conoscere il bambino e portare il regalo.")]),
("Testo informativo: «Il servizio di bike sharing di Padova cambia regole. Da gennaio la prima mezz'ora di ogni noleggio è gratuita per chi ha l'abbonamento annuale, mentre chi paga a corsa spende un euro ogni venti minuti. Le biciclette elettriche costano il doppio. Le bici si possono lasciare solo nelle stazioni segnate sull'app: chi le lascia altrove paga una penale.»",
 [("Chi non paga la prima mezz'ora?",
   "Chi ha l'abbonamento annuale", ["Chi usa la bici elettrica", "Chi paga a ogni corsa", "Chi abita in centro"],
   "La prima mezz'ora gratuita vale per chi ha l'abbonamento annuale."),
  ("Che cosa succede a chi lascia la bici fuori dalle stazioni?",
   "Deve pagare una multa", ["Perde l'abbonamento", "Non può più usare l'app", "Non succede nulla"],
   "Chi lascia la bici fuori dalle stazioni indicate paga una penale, cioè una somma come punizione.")]),
("Racconto: «Da bambina, Teresa passava le estati dalla zia a Positano. La zia aveva una piccola pensione con sei camere e Teresa la aiutava a preparare la colazione per gli ospiti. Imparò così qualche parola di tedesco e di inglese, e capì presto che le piaceva parlare con persone di tutto il mondo. Molti anni dopo, quando la zia andò in pensione, fu lei a prendere in mano l'albergo.»",
 [("Che cosa faceva Teresa d'estate da bambina?",
   "Aiutava con le colazioni", ["Studiava tedesco a scuola", "Lavorava in un grande albergo", "Andava al mare con gli ospiti"],
   "Teresa aiutava la zia a preparare la colazione per gli ospiti della pensione."),
  ("Che cosa è successo molti anni dopo?",
   "Ora la gestisce Teresa", ["La zia ha venduto la pensione", "Teresa si è trasferita in Germania", "La pensione ha chiuso"],
   "Quando la zia è andata in pensione, è stata Teresa a prendere in mano l'albergo.")]),
("Email: «Gentile cliente, la informiamo che dal 1° marzo la nostra agenzia di Cremona si trasferisce in via Platina 14, a cinquanta metri dalla vecchia sede. L'orario resta lo stesso. Durante il trasloco, venerdì 28 febbraio, l'agenzia sarà chiusa, ma il servizio clienti risponderà regolarmente al telefono. Il suo conto e la sua carta non subiscono alcun cambiamento. Banca Padana»",
 [("Che cosa cambia per i clienti dell'agenzia?",
   "L'indirizzo dell'ufficio", ["L'orario di apertura", "Il numero della carta", "Le spese del conto"],
   "L'agenzia si trasferisce in via Platina 14. L'orario, il conto e la carta restano gli stessi."),
  ("Che cosa succede il 28 febbraio?",
   "L'agenzia resta chiusa", ["Si apre la nuova sede", "Il telefono non funziona", "Le carte vengono bloccate"],
   "Il 28 febbraio, giorno del trasloco, l'agenzia è chiusa, ma il servizio clienti risponde al telefono.")]),
("Articolo: «Da quest'anno a Siena le persone sopra i settantacinque anni possono chiedere un'ora di compagnia a settimana a uno studente universitario. Gli studenti che partecipano leggono il giornale con gli anziani, li accompagnano dal medico o fanno due passi insieme. In cambio, l'università riconosce loro alcuni crediti. Molti studenti dicono di aver imparato più di quanto si aspettavano dalle storie dei loro nuovi amici.»",
 [("Che cosa ricevono gli studenti per questo servizio?",
   "Dei crediti universitari", ["Uno stipendio mensile", "Una stanza in affitto", "Un abbonamento ai giornali"],
   "In cambio del servizio, l'università riconosce agli studenti alcuni crediti."),
  ("Che cosa dicono molti studenti?",
   "Che hanno imparato molto", ["Che il servizio è troppo faticoso", "Che vorrebbero più ore pagate", "Che gli anziani parlano poco"],
   "Molti studenti dicono di aver imparato più del previsto dalle storie degli anziani.")]),
("Lettera di reclamo: «Spettabile ditta, il 3 aprile ho acquistato sul vostro sito un paio di scarpe da trekking numero 41. Mi sono arrivate due scarpe di numero diverso: la destra 41 e la sinistra 43. Ho scritto due volte al servizio clienti senza ricevere risposta. Vi chiedo di sostituirle al più presto o di rimborsarmi. Allego la foto delle scarpe e lo scontrino. Distinti saluti, Ugo Ferrandi»",
 [("Qual è il problema delle scarpe?",
   "Le due scarpe hanno misure diverse", ["Sono arrivate con un mese di ritardo", "Sono di un altro colore", "Sono rotte sulla punta"],
   "Ugo ha ricevuto la scarpa destra numero 41 e la sinistra numero 43."),
  ("Che cosa ha già fatto Ugo prima di scrivere questa lettera?",
   "Ha scritto due volte senza risposta", ["Ha riportato le scarpe al negozio", "Ha telefonato al direttore", "Ha ricevuto un rimborso parziale"],
   "Ugo dice di aver scritto due volte al servizio clienti senza ricevere risposta.")]),
("Testo: «Il mercato coperto di Livorno, chiamato da tutti «il Mercato Centrale», è aperto dal lunedì al sabato. Al piano terra si vendono soprattutto pesce, carne e formaggi, mentre al primo piano ci sono frutta, verdura e alcuni banchi dove si può mangiare. Il martedì mattina arrivano i contadini delle colline vicine con prodotti di stagione. Per chi viene in auto, il parcheggio sotterraneo è gratuito per la prima ora.»",
 [("Dove si può comprare la verdura nel mercato?",
   "Al primo piano", ["Al piano terra", "Nel parcheggio", "Solo fuori dal mercato"],
   "Frutta e verdura sono al primo piano; al piano terra ci sono pesce, carne e formaggi."),
  ("Che cosa succede il martedì mattina?",
   "Vengono a vendere i contadini della zona", ["Il mercato è chiuso", "Il parcheggio è gratuito tutto il giorno", "Si vendono solo formaggi"],
   "Il martedì mattina arrivano i contadini delle colline vicine con i prodotti di stagione.")]),
("Email: «Caro Rocco, ti scrivo dall'ufficio perché a casa la connessione non funziona da tre giorni. Il tecnico viene solo lunedì. Per questo non riesco a mandarti stasera le foto del viaggio in Puglia, come ti avevo promesso. Se vuoi, domani pomeriggio passo da te con la chiavetta e le guardiamo insieme davanti a un caffè. Fammi sapere. Agnese»",
 [("Perché Agnese non manda le foto?",
   "A casa non ha internet", ["Ha perso la chiavetta", "Il computer dell'ufficio è rotto", "Le foto non sono venute bene"],
   "Agnese spiega che a casa la connessione non funziona da tre giorni."),
  ("Che cosa propone Agnese a Rocco?",
   "Di vedere le foto insieme da lui", ["Di andare insieme in Puglia", "Di chiamare il tecnico", "Di mandargli le foto lunedì per email"],
   "Agnese propone di passare da Rocco il giorno dopo con la chiavetta per guardare le foto insieme.")]),
("Articolo: «In molte città italiane cresce il numero delle persone che lavorano da casa almeno due giorni a settimana. A Milano alcuni bar si sono adattati: offrono prese elettriche a ogni tavolo e un buon collegamento a internet, chiedendo in cambio di ordinare almeno una consumazione ogni due ore. I proprietari dicono che così riempiono i locali anche al mattino, quando prima erano quasi vuoti.»",
 [("Che cosa chiedono i bar a chi lavora ai tavoli?",
   "Di ordinare ogni tanto qualcosa", ["Di pagare un abbonamento", "Di venire solo al pomeriggio", "Di portare il proprio computer"],
   "I bar chiedono di ordinare almeno una consumazione ogni due ore."),
  ("Perché ai proprietari conviene questa idea?",
   "Hanno clienti anche di mattina", ["Risparmiano sulla corrente", "Possono chiudere prima la sera", "Vendono anche computer"],
   "I proprietari dicono che così il locale si riempie anche al mattino, quando prima era quasi vuoto.")]),
("Lettera di un lettore: «Abito a Cosenza da trent'anni e ho sempre amato il centro storico. Negli ultimi tempi, però, molti negozi hanno chiuso e le vie sono vuote dopo le otto di sera. Secondo me il Comune dovrebbe aiutare i giovani che vogliono aprire una bottega, per esempio con affitti più bassi per i primi anni. Così il centro tornerebbe vivo e non sarebbe solo un posto per i turisti. Pasquale R.»",
 [("Che cosa preoccupa Pasquale?",
   "Il centro storico si sta svuotando", ["I turisti sono troppi", "Gli affitti stanno scendendo", "Ci sono troppi negozi nuovi"],
   "Pasquale scrive che molti negozi hanno chiuso e le vie sono vuote la sera."),
  ("Che cosa propone Pasquale?",
   "Affitti ridotti per le nuove botteghe", ["Più parcheggi in centro", "Negozi aperti di notte", "Una festa per i turisti"],
   "Pasquale propone che il Comune aiuti i giovani con affitti più bassi nei primi anni.")]),
]

Q = [(text + " " + q, key, wrong, expl) for text, items in T for (q, key, wrong, expl) in items]
